#!/usr/bin/env node
/**
 * Bundles packages/shared/content/legal/*.md into legalMarkdownBundle.generated.ts
 * for web + mobile static legal documents.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');
const CONTENT_DIR = path.join(ROOT, 'packages/shared/content/legal');
const OUT_FILE = path.join(ROOT, 'packages/shared/src/legal/legalMarkdownBundle.generated.ts');

const SLUGS = ['terms', 'privacy'];
const LOCALES = ['en', 'he', 'ru', 'ar', 'fr', 'es', 'de'];

function escapeTemplateLiteral(value) {
    return value.replaceAll('\\', '\\\\').replaceAll('`', '\\`').replaceAll('${', '\\${');
}

const bundle = {};
for (const slug of SLUGS) {
    bundle[slug] = {};
    for (const locale of LOCALES) {
        const file = path.join(CONTENT_DIR, `${slug}.${locale}.md`);
        if (!fs.existsSync(file)) {
            console.error(`Missing legal markdown: ${path.relative(ROOT, file)}`);
            process.exit(1);
        }
        bundle[slug][locale] = fs.readFileSync(file, 'utf8');
    }
}

let ts = `/* eslint-disable */\n/** AUTO-GENERATED by scripts/generate-legal-bundle.mjs — do not edit. */\n\nimport type { Language } from '../i18n/languages';\nimport type { LegalSlug } from '../types';\n\nexport const LEGAL_MARKDOWN_RAW: Record<LegalSlug, Record<Language, string>> = {\n`;

for (const slug of SLUGS) {
    ts += `  ${slug}: {\n`;
    for (const locale of LOCALES) {
        ts += `    ${locale}: \`${escapeTemplateLiteral(bundle[slug][locale])}\`,\n`;
    }
    ts += `  },\n`;
}
ts += `};\n`;

fs.writeFileSync(OUT_FILE, ts);
console.log(`Wrote ${path.relative(ROOT, OUT_FILE)}`);
